import sys, json


def solve(request):
    initial = request['initial']
    final = request['final']
    txns = request['transactions']
    n = len(txns)

    # Universe of keys: anything that can ever be present or observed.
    keyset = set(initial) | set(final)
    for t in txns:
        for op in t['ops']:
            if op[0] == 'scan':
                keyset.add(op[1])
                keyset.add(op[2])
                for pr in op[3]:
                    keyset.add(pr[0])
            else:
                keyset.add(op[1])
    keylist = sorted(keyset)
    K = len(keylist)
    kidx = {k: i for i, k in enumerate(keylist)}
    NONE = None
    init_t = tuple(initial.get(k) for k in keylist)
    final_t = tuple(final.get(k) for k in keylist)

    if n == 0:
        return {"order": []} if init_t == final_t else {"order": None}

    GET, PUT, DEL, CAS, SCAN = 0, 1, 2, 3, 4
    compiled = []   # per txn: list of ops in index space
    wmask = []      # per txn: bitmask of keys it may write
    umask = []      # per txn: bitmask of keys it writes unconditionally (put/del)
    mayset = []     # per txn: per-key set of values it may assign (None = delete)
    reqs = []       # per txn: (0,key,value) value must be achievable / (1,key) absence must be achievable
    ids = []
    starts = []
    ends = []
    for t in txns:
        ids.append(t['id'])
        starts.append(t['start'])
        ends.append(t['end'])
        cops = []
        wm = 0
        um = 0
        ms = [set() for _ in range(K)]
        rq = []
        for op in t['ops']:
            kind = op[0]
            if kind == 'get':
                i = kidx[op[1]]
                cops.append((GET, i, op[2]))
                rq.append((0, i, op[2]))
            elif kind == 'put':
                i = kidx[op[1]]
                cops.append((PUT, i, op[2]))
                wm |= 1 << i
                um |= 1 << i
                ms[i].add(op[2])
            elif kind == 'del':
                i = kidx[op[1]]
                cops.append((DEL, i))
                wm |= 1 << i
                um |= 1 << i
                ms[i].add(None)
            elif kind == 'cas':
                i = kidx[op[1]]
                cops.append((CAS, i, op[2], op[3], op[4]))
                wm |= 1 << i
                ms[i].add(op[3])  # may be None (delete)
                if op[4]:
                    rq.append((0, i, op[2]))
            else:  # scan
                low, high, expected = op[1], op[2], op[3]
                idxs = tuple(i for i, k in enumerate(keylist) if low <= k < high)
                cops.append((SCAN, idxs, expected))
                expk = set()
                for pr in expected:
                    j = kidx[pr[0]]
                    expk.add(j)
                    rq.append((0, j, pr[1]))
                for j in idxs:
                    if j not in expk:
                        rq.append((1, j))
        compiled.append(cops)
        wmask.append(wm)
        umask.append(um)
        mayset.append(ms)
        reqs.append(rq)

    # Interval precedence: a.end <= b.start  =>  a before b.
    pred = [0] * n
    for i in range(n):
        ei = ends[i]
        for j in range(n):
            if i != j and ei <= starts[j]:
                pred[j] |= 1 << i

    full = (1 << n) - 1
    failed = set()
    agg_cache = {}

    def simulate(t, s):
        st = list(s)
        for op in compiled[t]:
            c = op[0]
            if c == GET:
                if st[op[1]] != op[2]:
                    return None
            elif c == PUT:
                st[op[1]] = op[2]
            elif c == DEL:
                st[op[1]] = None
            elif c == CAS:
                ok = st[op[1]] == op[2]
                if ok != op[4]:
                    return None
                if ok:
                    st[op[1]] = op[3]
            else:
                if [[keylist[i], st[i]] for i in op[1] if st[i] is not None] != op[2]:
                    return None
        return tuple(st)

    def aggregate(rem):
        # unions of may-assign values per key over txns in rem; plus write masks
        agg = agg_cache.get(rem)
        if agg is None:
            unions = [set() for _ in range(K)]
            wm = 0
            um = 0
            m = rem
            while m:
                b = m & -m
                t = b.bit_length() - 1
                m ^= b
                wm |= wmask[t]
                um |= umask[t]
                ms = mayset[t]
                for i in range(K):
                    if ms[i]:
                        unions[i] |= ms[i]
            agg = (tuple(frozenset(u) for u in unions), wm, um)
            agg_cache[rem] = agg
        return agg

    sys.setrecursionlimit(100000)

    def search(mask, s):
        if mask == full:
            return () if s == final_t else None
        mkey = (mask, s)
        if mkey in failed:
            return None
        rem = full ^ mask
        unions, wm, um = aggregate(rem)
        # Final-state reachability.
        for i in range(K):
            fi = final_t[i]
            if (um >> i) & 1:
                # Some remaining txn unconditionally rewrites key i:
                # the final value must be assignable by some remaining txn.
                if fi not in unions[i]:
                    failed.add(mkey)
                    return None
            else:
                # Only conditional (cas) writers or none: value may stay s[i].
                if fi != s[i] and fi not in unions[i]:
                    failed.add(mkey)
                    return None
        # Read-observation achievability for every remaining txn.
        m = rem
        while m:
            b = m & -m
            t = b.bit_length() - 1
            m ^= b
            for r in reqs[t]:
                i = r[1]
                if r[0] == 0:
                    v = r[2]
                    if s[i] != v and v not in unions[i]:
                        failed.add(mkey)
                        return None
                else:
                    if s[i] is not None and None not in unions[i]:
                        failed.add(mkey)
                        return None
        # Branch over ready candidates.
        m = rem
        while m:
            b = m & -m
            t = b.bit_length() - 1
            m ^= b
            if pred[t] & rem:
                continue
            s2 = simulate(t, s)
            if s2 is None:
                continue
            res = search(mask | b, s2)
            if res is not None:
                return (ids[t],) + res
        failed.add(mkey)
        return None

    ans = search(0, init_t)
    return {"order": list(ans) if ans is not None else None}


def main():
    out = []
    for line in sys.stdin:
        if not line.strip():
            continue
        out.append(json.dumps(solve(json.loads(line))))
    sys.stdout.write(''.join(o + '\n' for o in out))


if __name__ == '__main__':
    main()
