import json, random, sys
sys.path.insert(0, '/app')
from public_contract import valid_history
from main import solve
from test_random import gen_random_case, gen_sat_case

# Independent checker: plain precedence+simulation backtracking, NO memoization,
# NO fancy prunings (different code path from solver). Used to confirm UNSAT.
def indep_sat(req, node_limit=2_000_000):
    txns = req['transactions']
    n = len(txns)
    pred = [0]*n
    for i in range(n):
        for j in range(n):
            if i != j and txns[i]['end'] <= txns[j]['start']:
                pred[j] |= 1 << i
    d0 = dict(req['initial'])
    final = req['final']
    ops = [t['ops'] for t in txns]
    full = (1 << n) - 1
    state = [0]  # node counter

    def sim(i, d):
        d = dict(d)
        for op in ops[i]:
            k = op[0]
            if k == 'get':
                if d.get(op[1]) != op[2]: return None
            elif k == 'put':
                d[op[1]] = op[2]
            elif k == 'del':
                d.pop(op[1], None)
            elif k == 'cas':
                ok = d.get(op[1]) == op[2]
                if ok != op[4]: return None
                if ok:
                    if op[3] is None: d.pop(op[1], None)
                    else: d[op[1]] = op[3]
            else:
                if sorted([[k2, v] for k2, v in d.items() if op[1] <= k2 < op[2]]) != op[3]:
                    return None
        return d

    def rec(mask, d):
        state[0] += 1
        if state[0] > node_limit:
            raise TimeoutError
        if mask == full:
            return d == final
        for i in range(n):
            b = 1 << i
            if mask & b or (pred[i] & (full ^ mask)):
                continue
            d2 = sim(i, d)
            if d2 is not None and rec(mask | b, d2):
                return True
        return False
    try:
        return rec(0, d0)
    except TimeoutError:
        return 'timeout'

def run(seeds):
    bad = to = satn = unsatn = 0
    for seed in seeds:
        rng = random.Random(seed)
        # force n=9..10 random-observation cases (mostly unsat)
        req = gen_random_case(rng, nmax=10)
        while not (9 <= len(req['transactions']) <= 10):
            rng = random.Random(seed * 100003 + 7)
            req = gen_random_case(rng, nmax=10)
            break
        req = json.loads(json.dumps(req))
        got = solve(req)['order']
        ref = indep_sat(req)
        if ref == 'timeout':
            to += 1
            if got is not None and not valid_history(req, got):
                print('INVALID witness (timeout ref)', seed); bad += 1
            continue
        if ref:
            satn += 1
            if got is None or not valid_history(req, got):
                print('MISMATCH sat', seed, got); print(json.dumps(req)); bad += 1
        else:
            unsatn += 1
            if got is not None:
                print('MISMATCH unsat', seed, got); print(json.dumps(req)); bad += 1
    print(f'big-n test: sat={satn} unsat={unsatn} ref-timeout={to} bad={bad}')

if __name__ == '__main__':
    run(range(100000, 100060))
