    txns = [{'id': f't{i}', 'start': rng.randint(0, 6), 'end': 0, 'ops': []} for i in range(n)]
    for t in txns:
        t['end'] = t['start'] + rng.randint(1, 12)   # heavy overlap
    pred = {i: set() for i in range(n)}
    for i in range(n):
        for j in range(n):
            if i != j and txns[i]['end'] <= txns[j]['start']:
                pred[j].add(i)
    order = []; placed = set()
    while len(order) < n:
        cands = [i for i in range(n) if i not in placed and pred[i] <= placed]
        c = rng.choice(cands); order.append(c); placed.add(c)
    d = dict(initial)
    for i in order:
        t = txns[i]
        for _ in range(rng.randint(2, 5)):
            r = rng.random(); k = rng.choice(keys)
            if r < 0.35:
                t['ops'].append(['get', k, d.get(k)])
            elif r < 0.55:
                v = rng.randint(0, 1); t['ops'].append(['put', k, v]); d[k] = v
            elif r < 0.65:
                t['ops'].append(['del', k]); d.pop(k, None)
            elif r < 0.85:
                old = d.get(k) if rng.random() < 0.7 else rng.choice([None, 0, 1])
                ok = d.get(k) == old
                new = rng.choice([None, 0, 1])
                t['ops'].append(['cas', k, old, new, ok])
                if ok:
                    if new is None: d.pop(k, None)
                    else: d[k] = new
            else:
                lo, hi = sorted(rng.sample(keys, 2))
                pairs = sorted([[k2, v] for k2, v in d.items() if lo <= k2 < hi])
                t['ops'].append(['scan', lo, hi, pairs])
    req = {'initial': initial, 'final': d, 'transactions': txns}
    if flip:
        # corrupt one observation -> likely unsat but deep
        t = rng.choice(txns)
        oi = rng.randrange(len(t['ops']))
        op = t['ops'][oi]
        if op[0] == 'get':
            op[2] = rng.choice([None, 0, 1])
        elif op[0] == 'cas':
            op[4] = not op[4]
        elif op[0] == 'scan':
            op[3] = [[rng.choice(keys), rng.randint(0,1)]]
        else:
            op[0]  # put/del: change nothing observable; flip final instead
            k = rng.choice(keys)
            if rng.random() < 0.5: req['final'] = dict(d); req['final'][k] = 1 - d.get(k, 0)
            else: req['final'] = dict(d); req['final'].pop(k, None); req['final'][k + 'z'] = 1
            req['final'] = {kk: vv for kk, vv in req['final'].items() if kk in keys}
    return req

